//! The "Command flags" section of docs/reference.md, generated from the
//! CLI's own definition so the page can't drift from `--help` (#689).
//! The test fails when the page differs; to rewrite the section:
//!
//! ```sh
//! UPDATE_REFERENCE=1 cargo test -p ganymede-cli --bin ganymede reference
//! ```

use clap::{ArgAction, Command, CommandFactory};

const START: &str =
    "<!-- command-flags:start (generated by crates/ganymede-cli/src/reference.rs) -->";
const END: &str = "<!-- command-flags:end -->";

const GLOBAL_START: &str =
    "<!-- global-flags:start (generated by crates/ganymede-cli/src/reference.rs) -->";
const GLOBAL_END: &str = "<!-- global-flags:end -->";

/// The command whose flags the hand-written "Server flags" table lists,
/// with their config keys.
const SERVER: &str = "serve";

/// Table cell text: one line, with `|` escaped.
fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}

/// The flag as `--help` shows it: `-o`, `--output <PATH>`.
fn flag(arg: &clap::Arg) -> String {
    let mut names = vec![];
    if let Some(short) = arg.get_short() {
        names.push(format!("`-{short}`"));
    }
    // A value that may be left out shows as `[<NAME>]`, as in `--help`.
    let optional = arg.get_num_args().is_some_and(|n| n.min_values() == 0);
    let value = match arg.get_action() {
        ArgAction::Set | ArgAction::Append => {
            let names = arg
                .get_value_names()
                .map(|v| {
                    v.iter()
                        .map(|n| format!("<{n}>"))
                        .collect::<Vec<_>>()
                        .join(" ")
                })
                .unwrap_or_else(|| format!("<{}>", arg.get_id().as_str().to_uppercase()));
            if optional {
                format!(" [{names}]")
            } else {
                format!(" {names}")
            }
        }
        _ => String::new(),
    };
    names.push(format!("`--{}{value}`", arg.get_long().unwrap_or_default()));
    names.join(", ")
}

/// What the flag does: its help text, and its default when it has one.
fn effect(arg: &clap::Arg) -> String {
    let text = arg.get_help().map(|h| h.to_string()).unwrap_or_default();
    let defaults: Vec<_> = arg
        .get_default_values()
        .iter()
        .map(|v| v.to_string_lossy().into_owned())
        .collect();
    let shows_default = matches!(arg.get_action(), ArgAction::Set | ArgAction::Append);
    let text = text.trim_end().trim_end_matches('.');
    // Help text that already names its default ("Default: ...") keeps it.
    let names_default = text.contains("Default") || text.contains("(default");
    let text = if shows_default && !defaults.is_empty() && !names_default {
        format!("{text}. Default `{}`.", defaults.join(" "))
    } else if text.is_empty() {
        String::new()
    } else {
        format!("{text}.")
    };
    // `--help` doesn't say a flag can be given more than once; the page does.
    let text = if matches!(arg.get_action(), ArgAction::Append) && !text.contains("epeat") {
        format!("{text} Repeatable.")
    } else {
        text
    };
    cell(text.trim())
}

/// What a command's table can't say, under it (#769).
fn note(path: &str) -> Option<&'static str> {
    match path {
        "nb publish" => Some(
            "The page replaces the notebook's directory with `.` and the home \
             directory with `~`, and nothing else: a secret a cell printed (a \
             token, an API key, an environment variable) goes in as it is, so \
             read the page before sharing it. See \
             [Publishing a notebook](mcp.md#publishing-a-notebook).",
        ),
        _ => None,
    }
}

/// Commands that take every `serve` flag.
fn flattens_server(path: &str) -> bool {
    path == "lab" || path == "ui"
}

/// The flags `--help` lists for a command, without clap's own `--help`
/// and `--version` (a command's `--version <V>` stays).
fn shown(cmd: &Command) -> impl Iterator<Item = &clap::Arg> {
    cmd.get_arguments()
        .filter(|a| !a.is_hide_set() && a.get_long().is_some())
        .filter(|a| !matches!(a.get_action(), ArgAction::Help | ArgAction::Version))
}

/// A Flag | Effect table.
fn table<'a>(flags: impl IntoIterator<Item = &'a clap::Arg>) -> String {
    let mut out = String::from("| Flag | Effect |\n| --- | --- |\n");
    for arg in flags {
        out.push_str(&format!("| {} | {} |\n", flag(arg), effect(arg)));
    }
    out
}

/// Clap hasn't propagated global flags yet, so each command lists only the
/// flags it declares. The root's are the "Flags for every command" table,
/// and a subcommand of any other command with global flags says it takes
/// them (`mcp call` takes `mcp`'s).
fn walk(cmd: &Command, path: &str, server: &[String], out: &mut String) {
    walk_under(cmd, path, None, server, out);
}

fn walk_under(
    cmd: &Command,
    path: &str,
    inherits: Option<&str>,
    server: &[String],
    out: &mut String,
) {
    let flags: Vec<_> = shown(cmd)
        // lab and ui take serve's flags, which the "Server flags" table lists.
        .filter(|a| {
            !(flattens_server(path) && server.iter().any(|s| Some(s.as_str()) == a.get_long()))
        })
        .collect();
    if !path.is_empty() && path != SERVER && !flags.is_empty() {
        out.push_str(&format!("\n### `{path}`\n\n{}", table(flags)));
        if flattens_server(path) {
            out.push_str("\nAnd the [server flags](#server-flags).\n");
        }
        if let Some(parent) = inherits {
            out.push_str(&format!("\nAnd `{parent}`'s flags.\n"));
        }
        if let Some(note) = note(path) {
            out.push_str(&format!("\n{note}\n"));
        }
    }
    let globals = !path.is_empty() && shown(cmd).any(|a| a.is_global_set());
    let inherits = if globals { Some(path) } else { inherits };
    for sub in cmd.get_subcommands() {
        if sub.is_hide_set() || sub.get_name() == "help" {
            continue;
        }
        let p = if path.is_empty() {
            sub.get_name().to_string()
        } else {
            format!("{path} {}", sub.get_name())
        };
        walk_under(sub, &p, inherits, server, out);
    }
}

/// The section's Markdown, between its markers.
fn section() -> String {
    let cli = crate::Cli::command();
    let server: Vec<String> = cli
        .find_subcommand(SERVER)
        .expect("serve")
        .get_arguments()
        .filter_map(|a| a.get_long().map(str::to_string))
        .collect();
    let mut out = String::new();
    walk(&cli, "", &server, &mut out);
    format!("{START}\n{out}\n{END}")
}

/// The "Flags for every command" table: the root command's flags.
fn global() -> String {
    let cli = crate::Cli::command();
    format!("{GLOBAL_START}\n{}{GLOBAL_END}", table(shown(&cli)))
}

/// Compares the text between `start` and `end` in docs/reference.md with
/// `generated`, or rewrites it with UPDATE_REFERENCE set.
fn check(start: &str, end: &str, generated: &str) {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/reference.md");
    let doc = std::fs::read_to_string(path).unwrap();
    let (s, e) = (
        doc.find(start).expect("start marker"),
        doc.find(end).expect("end marker"),
    );
    let current = &doc[s..e + end.len()];
    if current != generated {
        if std::env::var_os("UPDATE_REFERENCE").is_some() {
            std::fs::write(path, doc.replace(current, generated)).unwrap();
            return;
        }
        panic!(
            "docs/reference.md's flags differ from the CLI. Rewrite them with\n  \
             UPDATE_REFERENCE=1 cargo test -p ganymede-cli --bin ganymede reference"
        );
    }
}

#[test]
fn reference_lists_every_command_flag() {
    check(START, END, &section());
}

#[test]
fn reference_lists_the_flags_for_every_command() {
    check(GLOBAL_START, GLOBAL_END, &global());
}

/// The hand-written "Server flags" table names every `serve` flag.
#[test]
fn server_flags_table_lists_every_serve_flag() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/reference.md");
    let doc = std::fs::read_to_string(path).unwrap();
    let start = doc.find("\n## Server flags").expect("Server flags section");
    let rest = &doc[start + 1..];
    let table = &rest[..rest[3..].find("\n## ").map_or(rest.len(), |e| e + 3)];
    let cli = crate::Cli::command();
    let missing: Vec<_> = shown(cli.find_subcommand(SERVER).expect("serve"))
        .filter_map(|a| a.get_long())
        .filter(|long| {
            !table.contains(&format!("`--{long}`")) && !table.contains(&format!("`--{long} <"))
        })
        .collect();
    assert!(
        missing.is_empty(),
        "docs/reference.md's Server flags table is missing {missing:?}"
    );
}
